package com.jamshed.hrms.controller;
import com.jamshed.hrms.entity.*; import com.jamshed.hrms.exception.*; import com.jamshed.hrms.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/attendance") public class AttendanceController {private final AttendanceRepository r;private final EmployeeRepository er;public AttendanceController(AttendanceRepository r,EmployeeRepository er){this.r=r;this.er=er;}@GetMapping public List<Attendance> all(){return r.findAll();}
 @PostMapping("/clock-in/{employeeId}") public Attendance clockIn(@PathVariable Long employeeId){Employee e=er.findById(employeeId).orElseThrow(()->new ResourceNotFoundException("Employee not found"));if(r.findAll().stream().anyMatch(existing->existing.getEmployee().getId().equals(employeeId) && LocalDate.now().equals(existing.getWorkDate())))throw new BusinessException("Attendance already recorded for today");Attendance a=Attendance.builder().employee(e).workDate(LocalDate.now()).checkIn(LocalDateTime.now()).status("PRESENT").build();return r.save(a);}
 @PostMapping("/clock-out/{id}") public Attendance clockOut(@PathVariable Long id){Attendance a=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Attendance not found"));if(a.getCheckOut()!=null)throw new BusinessException("Employee has already clocked out");a.setCheckOut(LocalDateTime.now());return r.save(a);} }
